(function(){var boxes=[].slice.call(document.querySelectorAll('input[data-question]')), status=document.getElementById('chosen');function selected(){return boxes.filter(function(x){return x.checked})}function refresh(){var count=selected().length;status.textContent=count?'已选择 '+count+' 项。建议优先讨论 1—2 个真实情境；复制后可按需删减。':'尚未选择。可以勾选上方最相关的情境，复制问题清单，仅保存在当前浏览器中，不会自动发送给作者。'}boxes.forEach(function(x){x.addEventListener('change',refresh)});function copy(text,btn){var prior=btn.textContent;function done(ok){btn.textContent=ok?'已复制':'请长按复制';setTimeout(function(){btn.textContent=prior},2200)}if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){done(true)}).catch(function(){fallback()})}else fallback();function fallback(){var el=document.createElement('textarea');el.value=text;el.style.position='fixed';el.style.left='-9999px';document.body.appendChild(el);el.select();var ok=false;try{ok=document.execCommand('copy')}catch(e){}el.remove();if(ok)done(true);else{prompt('请长按复制以下内容：',text);done(false)}}}document.getElementById('copy-summary').addEventListener('click',function(){var items=selected();copy(items.length?'我想进一步了解以下学习与成长问题：\n'+items.map(function(x,i){return (i+1)+'. 【'+x.dataset.topic+'】'+x.dataset.question}).join('\n')+'\n（先交流需求，再判断合适的支持方式。）':'想先聊聊孩子目前的一个具体学习或成长问题。',this)});document.getElementById('copy-wechat').addEventListener('click',function(){copy('18043054632',this)});document.getElementById('clear').addEventListener('click',function(){boxes.forEach(function(x){x.checked=false});refresh()});})();